import React from 'react';

import { declOfNum } from '@helpers/formatHelper';
import { round } from '@helpers/mathHelper';
import { info } from '@helpers/notificationHelper';
import PohAlert, { AlertVariant } from '@ui-kit/Alert';
import PohBadge, { BadgeVariant } from '@ui-kit/Badge/Badge';
import PohButton, { ButtonSize, ButtonVariant } from '@ui-kit/Button';
import PohCheckbox from '@ui-kit/Checkbox';
import PohInput, { InputTypes } from '@ui-kit/Input';
import PohCol from '@ui-kit/layout/Col';
import PohRow from '@ui-kit/layout/Row';
import { confirmModal2 } from '@ui-kit/Modal/modalsHelper';

import { IHikingData } from '../../../../@types/hiking.types';
import { IShoppingItem } from '../../shopping.types';

interface IShoppingEditModalProps {
  data: IShoppingItem;
  hikingData: IHikingData;
  onSave: (updatedItem: IShoppingItem) => void;
  onCancel: () => void;
  user: {
    id: number;
    name: string;
    photo: string;
  };
}

const ShoppingEditModal: React.FC<IShoppingEditModalProps> = ({
  data: defaultData,
  hikingData,
  onSave,
  onCancel,
  user,
}) => {
  const [data, setData] = React.useState<IShoppingItem>(defaultData);
  const [completed, setCompleted] = React.useState<boolean>(defaultData.isComplete);
  const sskey = `shopping_accept_${hikingData.id}`;
  const [showAttention, setShowAttention] = React.useState(!sessionStorage.getItem(sskey));

  const handleUpdate =
    <T,>(fieldName: keyof IShoppingItem) =>
    (v: T) => {
      setData((d) => ({ ...d, [fieldName]: v }));
    };

  const handleSave = () => {
    const updated = {
      ...data,
      isComplete: completed,
      dateComplete: completed ? new Date() : null,
      dateUpdate: new Date(),
      user,
    };

    setData(updated);
    onSave(updated);
  };

  return (
    <section className="mt-n3" style={{ minWidth: 360 }}>
      <PohRow className="mb-3">
        <PohCol sm={12}>
          {showAttention && (
            <PohAlert variant={AlertVariant.Success}>
              <PohButton
                size={ButtonSize.Small}
                variant={ButtonVariant.OutlineSuccess}
                className="float-end mt-n1 me-n2"
                onClick={async () => {
                  const ok = await confirmModal2(
                    <div>
                      <h5>Обращайте внимание на количество раз, когда нужен покупаемый продукт</h5>
                      <p>
                        Например: Если макароны нужны на 2 раза, лучше взять 2 пачки вместо 1
                        большой.
                      </p>

                      <h5>Обращайте внимание на количество участников</h5>
                      <p>
                        Например: Покупая пачку вкусного печенья в которой 8 штук и по граммам то
                        что нужно или даже больше, может оказаться грустно если в походе 9
                        человек{' '}
                      </p>
                    </div>,
                  );

                  if (ok) sessionStorage.setItem(sskey, 'ok');
                  setShowAttention(false);
                }}
              >
                Тык
              </PohButton>
              Здравый смысл важнее граммов!
            </PohAlert>
          )}
          <details>
            <summary className="d-flex">
              <PohBadge variant={BadgeVariant.Warning}>
                на {data.usages.length}
                &thinsp;
                {declOfNum(data.usages.length, ['раз', 'раза', 'раз'])}
              </PohBadge>
              :{' '}
              {data.usages.map((x) => (
                <PohBadge
                  className="me-1"
                  variant={BadgeVariant.Light}
                  key={x.name + x.date}
                  onClick={() =>
                    info(`${round(x.amount, 1)} г. ${x.name} ${x.date.toLocaleString()}`)
                  }
                >
                  {round(x.amount, 1)}
                  {hikingData.hikers.length > x.hikers.length && <sup>{x.hikers.length}</sup>}
                </PohBadge>
              ))}
            </summary>
            <table className="table table-sm table-bordered table-condensed table-striped">
              <thead>
                <tr>
                  <th>Дата</th>
                  <th>Блюдо</th>
                  <th>г.</th>
                </tr>
              </thead>
              <tbody>
                {data.usages.map((x) => (
                  <tr key={[x.date, x.name, x.amount].join('')}>
                    <td>{`${x.date.toLocaleDateString()} ${x.date.toLocaleTimeString().substr(0, 5)}`}</td>
                    <td>{x.name}</td>
                    <td className="text-end">{round(x.amount, 1)}</td>
                  </tr>
                ))}
              </tbody>
            </table>
          </details>
        </PohCol>
      </PohRow>
      <PohRow>
        <PohCol xs={6}>
          <PohInput
            required
            label={`Грамм (надо ${data.needAmount})`}
            type={InputTypes.number}
            value={data.amount.toString()}
            onChange={handleUpdate('amount')}
            onRealChange={(v) => +v > data.needAmount && !completed && setCompleted(true)}
            className="text-end"
          />
        </PohCol>
        <PohCol xs={6}>
          <PohInput
            required
            label="Цена"
            type={InputTypes.number}
            value={data.price.toString()}
            onChange={handleUpdate('price')}
            className="text-end"
          />
        </PohCol>
      </PohRow>
      <PohRow>
        <PohCol sm={12}>
          <PohInput
            label="Комментарий"
            placeholder="Введите коментарий"
            type={InputTypes.textarea}
            value={data?.comment || ''}
            onChange={handleUpdate('comment')}
          />
        </PohCol>
      </PohRow>
      <PohRow>
        <PohCol sm={12}>
          <PohCheckbox
            label="Полностью куплено"
            checked={completed}
            onChange={(c) => {
              if (c && data.amount === 0) {
                handleUpdate('amount')(data.needAmount);
              }

              setCompleted(c);
            }}
          />
        </PohCol>
      </PohRow>
      <footer className="mt-4 d-flex align-items-center justify-content-between">
        <PohButton variant={ButtonVariant.Secondary} onClick={onCancel}>
          Отмена
        </PohButton>
        <PohButton variant={ButtonVariant.Primary} onClick={handleSave}>
          Сохранить
        </PohButton>
      </footer>
    </section>
  );
};

export default ShoppingEditModal;
