import { filterHikersByDate } from '@apps/Hiking/menu/components/HikingMenuPrintStickers';

import { IShoppingItemDTO, IUpdateShoppingItemDTO } from './shopping.dto.types';
import { IShoppingItem } from './shopping.types';
import { IHiker } from '../../@types/hiking.types';

function parseUsages(csv: string, hikers: IHiker[]): IShoppingItem['usages'] {
  if (!csv?.length) {
    return [];
  }

  return csv.split(',').map((x) => {
    const [recipe, date, amount] = x.split('|');
    const d = new Date(date);
    const realHikers = hikers.filter(filterHikersByDate(d));

    return {
      name: recipe,
      date: d,
      amount: +amount * realHikers.length,
      hikers: realHikers,
    };
  });
}

export const mapShoppingItemToFront =
  (hikers: IHiker[]) =>
  (backItem: IShoppingItemDTO): IShoppingItem => {
    const usages = parseUsages(backItem.usages, hikers);
    return {
      id: +backItem.id,
      name: backItem.name,
      comment: backItem.comment,
      idProduct: +backItem.id_product,
      amount: +backItem.amount,
      needAmount: usages.reduce((s, v) => s + v.amount, 0),
      usages,
      price: +backItem.price,
      isComplete: +backItem.is_complete === 1,
      dateComplete: new Date(Date.parse(backItem.completed_at)),
      dateUpdate: new Date(Date.parse(backItem.updated_at)),
      user: backItem.id_user
        ? {
            id: +backItem.id_user,
            name: [backItem.uname, backItem.usurname].join(' '),
            photo: backItem.uphoto,
          }
        : null,
    };
  };

export function mapShoppingItemToBack(fntItem: IShoppingItem): IUpdateShoppingItemDTO {
  return {
    id: fntItem.id.toString(),
    amount: fntItem.amount.toString(),
    price: fntItem.price.toString(),
    is_complete: fntItem.isComplete ? '1' : '0',
    comment: fntItem?.comment || '',
  };
}
