import { get, handleApiError, post } from '@helpers/httpClient';

import { IShoppingItemDTO, IUpdateShoppingItemDTO } from './shopping.dto.types';

export async function getShoppingList(id_hiking: number): Promise<IShoppingItemDTO[]> {
  const res = await get('/ajax/hiking/menu/shopping_list.php', { id_hiking }).then(handleApiError);
  return Promise.resolve(res);
}

export async function editShoppingItem(data: IUpdateShoppingItemDTO) {
  const res = await post('/ajax/hiking/menu/shopping_edit.php', data).then(handleApiError);
  return Promise.resolve(res);
}

export async function initShoppingItems(id_hiking: number) {
  const res = await post('/ajax/hiking/menu/shopping_list_fill.php', { id_hiking }).then(
    handleApiError,
  );
  return Promise.resolve(res);
}
