import React from 'react';

import Cart from '@pohodnik/icons/svg/Commerce/Cart';
import clsx from 'clsx';

import { round } from '@helpers/mathHelper';
import PohAva from '@ui-kit/Ava';
import PohBadge, { BadgeVariant } from '@ui-kit/Badge/Badge';

import style from './style.module.less';
import { IShoppingItem } from '../../shopping.types';
interface IShoppingListItemProps {
  data: IShoppingItem;
}

const ShoppingListItem: React.FC<IShoppingListItemProps> = ({ data }) => {
  let date = data?.dateComplete?.toLocaleDateString();
  if (date === new Date().toLocaleDateString()) {
    date = data?.dateComplete?.toLocaleTimeString().substr(0, 5);
  }

  let amvar = BadgeVariant.Light;

  if (data.isComplete) {
    const alreadyDone = data.amount / data.needAmount;
    amvar = BadgeVariant.Danger;

    if (alreadyDone > 0.8) {
      amvar = BadgeVariant.Warning;
    }

    if (alreadyDone > 0.98) {
      amvar = BadgeVariant.Success;
    }
  }

  return (
    <div className="mx-n1 d-flex align-items-center justify-content-between">
      <span className={clsx('d-flex align-items-center', style.lh)}>
        {data.isComplete ? (
          <PohAva alt={data.user?.name} src={data.user?.photo} className="my-n2 ms-n2 me-2" />
        ) : (
          <Cart className="my-n2 ms-n2 me-2" />
        )}
        <div>
          <strong>{data.isComplete ? <del>{data.name}</del> : <span>{data.name}</span>}</strong>
          {data?.comment?.length > 0 && (
            <div>
              <em className="text-warning">
                <small>{data.comment}</small>
              </em>
            </div>
          )}
        </div>
      </span>
      <div className="d-flex align-items-end justify-content-center ms-2 me-n2">
        {data.isComplete ? (
          <em>
            {' '}
            <small>{date}</small>
          </em>
        ) : null}
        <PohBadge
          className="ms-1"
          rounded
          variant={amvar}
        >{`${round((data.amount / data.needAmount) * 100, 0)}%`}</PohBadge>
        <PohBadge className="ms-1" rounded variant={BadgeVariant.Info}>
          {round(data.needAmount, 1)}г.&nbsp;<small>[{data.usages.length}]</small>
        </PohBadge>
      </div>
    </div>
  );
};

export default ShoppingListItem;
